window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3cf85f21462fd37f"]={"versions": [{"id": "FIG-3cf85f21462fd37f", "releases": ["R17-03_R1.1.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodellspezifikation (Manifest Specification). Das Diagramm spezifiziert die statische Modellierungsstruktur für das Mapping von Anwendungsfehlern (<code>ApplicationError</code>) zwischen unterschiedlichen Service-Schnittstellen (<code>ServiceInterfaceApplicationErrorMapping</code>) im Kontext serviceorientierter Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceMappingSet</code> (Spezialisierung von <code>ARElement</code>): Bildet den Wurzelcontainer für Schnittstellen-Mappings und aggregiert über die Komposition <code>+elementMapping</code> mit Kardinalität <code>0..*</code> Instanzen von <code>ServiceInterfaceElementMapping</code>.</li>\n<li><code>ServiceInterfaceElementMapping</code> (Spezialisierung von <code>Identifiable</code>, abstrakt kursiv dargestellt): Abstrakte Basisklasse für Mappings einzelner Schnittstellenelemente.</li>\n<li><code>ServiceInterfaceApplicationErrorMapping</code> (Spezialisierung von <code>ServiceInterfaceElementMapping</code> via Generalisierungsbeziehung): Konkrete Mapping-Klasse zur Zuordnung von Fehlern.</li>\n<li><code>ApplicationError</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert einen definierten Anwendungsfehler mit dem Attribut <code>+errorCode : Integer</code>.</li>\n<li>Assoziationen von <code>ServiceInterfaceApplicationErrorMapping</code> auf <code>ApplicationError</code>:</li>\n<li><code>+sourcePossibleError</code>: Gerichtete Assoziation auf genau einen Quell-<code>ApplicationError</code> (Kardinalität <code>1</code>).</li>\n<li><code>+targetPossibleError</code>: Gerichtete Assoziation auf genau einen Ziel-<code>ApplicationError</code> (Kardinalität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als metamodellbasiertes Strukturdiagramm stellt das Klassendiagramm keinen dynamischen Ausführungs- oder Sequenzablauf dar. Zur Laufzeit bzw. Konfigurationszeit bestimmt die statische Zuordnung, welcher Quellfehlercode bzw. <code>ApplicationError</code> einer Service-Schnittstelle auf welchen Ziel-<code>ApplicationError</code> einer korrespondierenden Service-Schnittstelle transformiert bzw. abgebildet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Modellierungswerkzeuge müssen sicherstellen, dass bei der Definition eines <code>ServiceInterfaceApplicationErrorMapping</code> innerhalb eines <code>ServiceInterfaceMappingSet</code> jeweils genau ein <code>sourcePossibleError</code> und genau ein <code>targetPossibleError</code> referenziert werden (Multiplizität jeweils strikt 1). Die referenzierten Fehler müssen gültige Instanzen vom Typ <code>ApplicationError</code> sein, welche über einen entsprechenden ganzzahligen <code>errorCode</code> verfügen.</p>"}, {"id": "FIG-ff8ac3778f62877b", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR-Metamodellspezifikation (Manifest Specification). Das Diagramm spezifiziert die statische Modellierungsstruktur für das Mapping von Anwendungsfehlern (<code>ApplicationError</code>) zwischen unterschiedlichen Service-Schnittstellen (<code>ServiceInterfaceApplicationErrorMapping</code>) im Kontext serviceorientierter Architekturen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>ServiceInterfaceMappingSet</code> (Spezialisierung von <code>ARElement</code>): Bildet den Wurzelcontainer für Schnittstellen-Mappings und aggregiert über die Komposition <code>+elementMapping</code> mit Kardinalität <code>0..*</code> Instanzen von <code>ServiceInterfaceElementMapping</code>.</li>\n<li><code>ServiceInterfaceElementMapping</code> (Spezialisierung von <code>Identifiable</code>, abstrakt kursiv dargestellt): Abstrakte Basisklasse für Mappings einzelner Schnittstellenelemente.</li>\n<li><code>ServiceInterfaceApplicationErrorMapping</code> (Spezialisierung von <code>ServiceInterfaceElementMapping</code> via Generalisierungsbeziehung): Konkrete Mapping-Klasse zur Zuordnung von Fehlern.</li>\n<li><code>ApplicationError</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert einen definierten Anwendungsfehler mit dem Attribut <code>+errorCode : Integer</code>.</li>\n<li>Assoziationen von <code>ServiceInterfaceApplicationErrorMapping</code> auf <code>ApplicationError</code>:</li>\n<li><code>+sourcePossibleError</code>: Gerichtete Assoziation auf genau einen Quell-<code>ApplicationError</code> (Kardinalität <code>1</code>).</li>\n<li><code>+targetPossibleError</code>: Gerichtete Assoziation auf genau einen Ziel-<code>ApplicationError</code> (Kardinalität <code>1</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als metamodellbasiertes Strukturdiagramm stellt das Klassendiagramm keinen dynamischen Ausführungs- oder Sequenzablauf dar. Zur Laufzeit bzw. Konfigurationszeit bestimmt die statische Zuordnung, welcher Quellfehlercode bzw. <code>ApplicationError</code> einer Service-Schnittstelle auf welchen Ziel-<code>ApplicationError</code> einer korrespondierenden Service-Schnittstelle transformiert bzw. abgebildet wird.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Entwickler und Modellierungswerkzeuge müssen sicherstellen, dass bei der Definition eines <code>ServiceInterfaceApplicationErrorMapping</code> innerhalb eines <code>ServiceInterfaceMappingSet</code> jeweils genau ein <code>sourcePossibleError</code> und genau ein <code>targetPossibleError</code> referenziert werden (Multiplizität jeweils strikt 1). Die referenzierten Fehler müssen gültige Instanzen vom Typ <code>ApplicationError</code> sein, welche über einen entsprechenden ganzzahligen <code>errorCode</code> verfügen.</p>"}], "trans": [{"from": "FIG-3cf85f21462fd37f", "to": "FIG-ff8ac3778f62877b", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
